function norm(s=''){return String(s).toLowerCase().normalize('NFD').replace(/[\u064b-\u065f\u0670]/g,'').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/ؤ/g,'و').replace(/ئ/g,'ي').replace(/ة/g,'ه').replace(/[^\p{L}\p{N}]+/gu,' ').trim()}
const SYN=[['سماد','اسمده','مغذيات','npk','fertilizer','fertilizers'],['بذور','تقاوي','seed','seeds'],['مبيد','مبيدات','pesticide','pesticides','حمايه'],['ري','تنقيط','irrigation','drip'],['ادوات','معدات','tools','equipment'],['بيت محمي','بيوت محميه','greenhouse','greenhouses'],['خيار','cucumber'],['طماطم','tomato'],['فلفل','pepper'],['حديد','iron'],['زنك','zinc']];
function expandedTerms(q){const base=norm(q);const out=new Set(base.split(/\s+/).filter(Boolean));SYN.forEach(g=>{if(g.some(x=>base.includes(norm(x))))g.forEach(x=>out.add(norm(x)))});return [...out]}
function score(p,q){if(!q.trim())return 1;const terms=expandedTerms(q);const hay=norm([p.ar,p.en,p.sku,p.brand,p.type_ar,p.type_en,(p.keywords||[]).join(' '),category(p.cat)?.ar,category(p.cat)?.en].join(' '));let s=0;const nq=norm(q);if(norm(p.sku)===nq)s+=100;if(norm(p.ar)===nq||norm(p.en)===nq)s+=70;if(norm(p.ar).includes(nq)||norm(p.en).includes(nq))s+=35;terms.forEach(x=>{if(hay.includes(x))s+=8});return s}
