function saveSearch(q){if(!q.trim())return;let h=get(K.searches,[]);h=[q.trim(),...h.filter(x=>norm(x)!==norm(q))].slice(0,6);set(K.searches,h)}
function searchPage(){const q=params.get('q')||'',rows=searchProducts(q);saveSearch(q);return pageHero('SEARCH',t('البحث','Search'),q?t(`نتائج البحث عن «${esc(q)}»`,`Results for “${esc(q)}”`):t('ابحث بالاسم أو SKU أو نوع المنتج.','Search by name, SKU or product type.'))+`<section class="gr16-section"><div class="gr16-container"><form class="gr17-search-page-form"><input name="q" value="${esc(q)}" placeholder="${t('مثال: سماد 20-20-20 أو GR-SE','Example: 20-20-20 or GR-SE')}"><button class="gr16-btn gr16-btn--primary">${t('بحث','Search')}</button></form>${q&&rows.length?grid(rows):q?zeroResults(q):`<div class="gr17-popular-searches"><h2>${t('ابدأ بكلمة','Start with a term')}</h2>${['بذور','سماد','مبيد','ري','tools','NPK'].map(x=>`<a href="${url('search.html',{q:x})}">${x}</a>`).join('')}</div>`}</div></section>`}
