function orderConfirmationPage(){const oid=params.get('order');const o=orders.find(x=>x.id===oid)||orders[0];if(!o)return pageHero('ORDER',t('لا يوجد طلب محفوظ','No saved order'))+`<section class="gr16-section"><div class="gr16-container gr16-empty"><a class="gr16-btn gr16-btn--primary" href="${url('index.html')}">${t('الرئيسية','Home')}</a></div></section>`;return `<section class="gr16-section"><div class="gr16-container gr17-confirm"><div class="gr17-success-mark">✓</div><span class="gr16-kicker">${esc(o.id)}</span><h1>${t('تم إنشاء الطلب داخل وضع التجربة','Order created in test mode')}</h1><p>${t('تم حفظ الطلب محليًا على هذا الجهاز فقط، ولن يتم إرساله إلى الشركة أو تحصيل أي مبلغ.','This order is saved locally on this device only. It is not sent to the company and no payment is collected.')}</p><div class="gr16-panel"><div class="gr16-summary-row"><span>${t('الاسم','Name')}</span><b>${esc(o.customer.name)}</b></div><div class="gr16-summary-row"><span>${t('الإمارة','Emirate')}</span><b>${esc(o.customer.emirate)}</b></div><div class="gr16-summary-row"><span>${t('الإجمالي','Total')}</span><b>${money(o.total)}</b></div></div><div class="gr17-step-actions"><a class="gr16-btn gr16-btn--primary" href="${url('account.html')}">${t('عرض طلباتي','View my orders')}</a><a class="gr16-btn gr16-btn--outline" href="${url('collection.html')}">${t('متابعة التسوق','Continue shopping')}</a></div></div></section>`}
