function staticPage(kind){const x=staticPages[kind];let body='';if(kind==='about')body=`<div class="gr20-brand-landing"><div class="gr20-brand-emblem"><img decoding="async" width="566" height="176" src="assets/golden-roots-logo.webp" alt="GOLDEN ROOTS"></div><div class="gr20-brand-copy"><span class="gr16-kicker">GOLDEN ROOTS</span><h1>${t('علامة زراعية بواجهة تجارية مرتبة.','An agricultural brand with a structured commercial experience.')}</h1><p>${t('جولدن روتس للزراعة ومستلزماتها تبني تجربة تجمع الكتالوج، العروض، طلبات الأفراد وطلبات المزارع والشركات في هوية واحدة واضحة.','Golden Roots Agriculture & Supplies brings catalog, offers, retail ordering and farm/business ordering into one clear brand experience.')}</p><div class="gr20-commercial-actions"><a class="gr16-btn gr16-btn--primary" href="${url('collection.html')}">${t('استكشف المتجر','Explore shop')}</a><a class="gr16-btn gr16-btn--outline" href="${url('contact.html')}">${t('تواصل معنا','Contact us')}</a></div></div></div>`;else if(kind==='contact')body=`<div class="gr16-quote-grid"><div class="gr16-quote-aside"><span class="gr16-kicker">CONTACT</span><h2>${t('اختر طريقة التواصل المناسبة','Choose the right way to contact us')}</h2><p>${t('للاستفسارات العامة استخدم النموذج. للطلبات الكبيرة استخدم صفحة المزارع والشركات عشان التفاصيل تكون أوضح.','Use the form for general enquiries. For larger orders, use the Farm & B2B page so the request is structured properly.')}</p><a class="gr16-btn gr16-btn--outline" href="${url('wholesale.html')}">${t('طلبات المزارع والشركات','Farm & B2B')}</a></div><form class="gr16-panel gr16-form" data-contact-form><label>${t('الاسم','Name')}<input required name="name" autocomplete="name"></label><label>${t('الهاتف أو البريد','Phone or email')}<input required name="contact"></label><label>${t('الرسالة','Message')}<textarea required name="message"></textarea></label><button class="gr16-btn gr16-btn--primary">${t('تجهيز الرسالة','Prepare message')}</button><small>${t('الإرسال الإلكتروني غير مفعل حاليًا؛ يتم حفظ الرسالة كمسودة على هذا الجهاز فقط.','Online submission is not enabled yet; the message is saved as a draft on this device only.')}</small></form></div>`;else body=`<div class="gr16-policy"><h2>${t('معلومات مهمة','Important information')}</h2><p>${t(x.copy_ar,x.copy_en)}</p><h2>${t('قبل بدء البيع','Before live selling')}</h2><p>${t('تُنشر الصياغة التشغيلية أو القانونية المعتمدة هنا قبل بدء البيع الفعلي.','Approved operational or legal wording is published here before live selling begins.')}</p></div>`;return pageHero(x.k,t(x.ar,x.en))+`<section class="gr16-section"><div class="gr16-container">${body}</div></section>`}
function faqPage(){const items=[[t('هل التوصيل متاح داخل كل الإمارات؟','Is delivery available across all emirates?'),t('الموقع مجهز لاختيار أي إمارة من الإمارات السبع، وتظهر رسوم ومدة التوصيل النهائية عند اعتماد التشغيل.','The site supports all seven emirates; final delivery rates and timing are shown when operations are enabled.')],[t('هل يمكن طلب كميات للمزرعة أو الشركة؟','Can farms or companies order in bulk?'),t('نعم، يوجد طلب سريع وقوائم مزرعة ومسار مستقل لطلب عرض سعر.','Yes. Quick Order, Farm Lists and Request Quote are available.')],[t('هل أقدر أحفظ المنتجات وأرجع لها؟','Can I save products for later?'),t('نعم، يمكنك استخدام المفضلة وقوائم المزرعة والسلة المحفوظة للرجوع لاختياراتك بسرعة.','Yes. Wishlist, Farm Lists and Saved Cart help you return to your selections quickly.')],[t('هل أقدر أبحث برقم SKU؟','Can I search by SKU?'),t('نعم، البحث يدعم اسم المنتج والقسم والكلمات العربية والإنجليزية ورقم SKU.','Yes. Search supports product names, categories, Arabic and English terms, and SKU.')]];return pageHero('FAQ',t('الأسئلة الشائعة','Frequently Asked Questions'))+`<section class="gr16-section"><div class="gr16-container gr16-accordion">${items.map(x=>`<details><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}</div></section>`}
